const P = (text, opts = {}) => new Paragraph({
  children: [new TextRun({ text, size: 24, font: "Times New Roman", italics: opts.i || false, bold: opts.b || false })],
  spacing: { line: 360, after: 120 },
  alignment: AlignmentType.JUSTIFIED, ...opts.para
});
const H1 = t => new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun({ text: t, size: 28, bold: true, font: "Times New Roman", color: "000000" })], spacing: { before: 240, after: 120 } });
